#include "room_rules_internal.hpp"
namespace wot::room {
int Rules::dropCapture(const ActorKey&victim,const ActorKey&attacker){const auto name=rule::actorString(victim);int dropped=0;for(int team=1;team<=2;++team){auto&cap=capture_[team];auto i=cap.contributors.find(name);if(i==cap.contributors.end())continue;dropped+=std::max(0,i->second);cap.contributors.erase(i);int points=0;for(const auto&p:cap.contributors)points+=std::max(0,p.second);auto&base=state_.rules.object["bases"].object[std::to_string(team)];base.object["points"]=integer(std::min(100,points));if(!points)cap.participants.clear();if(cap.contributors.empty())cap.cursor=0;const auto rate=std::min<std::int64_t>(3,intField(base,"invaders"));base.object["time_left"]=number(rate?double(std::max(0,100-points))/double(rate):0.);}
 const auto*source=state_.actor(attacker.first,attacker.second),*target=state_.actor(victim.first,victim.second);if(dropped&&source&&target&&attacker!=victim&&intField(*source,"team")!=intField(*target,"team"))increment(attacker,"dropped_capture_points",dropped);return dropped;}
void Rules::updateCapture(){using namespace rule;if(!accepting()||state_.server_tick%30||last_capture_tick_==state_.server_tick||!null(state_.battle_result))return;last_capture_tick_=state_.server_tick;
 const auto&bases=has(state_.resources,"capture_bases")?state_.resources.get("capture_bases"):state_.config.get("capture_bases");if(null(bases))return;
 struct Vehicle{ActorKey key;int team;double x,z;};std::vector<Vehicle> vehicles;for(const auto&k:std::array<const char*,2>{{"player","bot"}}){const auto&actors=std::string(k)=="bot"?state_.bots:state_.players;for(const auto&row:actors){const auto&a=row.second;if(!alive(a)||!(std::string(k)=="bot"?a.get("world_pose").truth():a.get("client_position").truth(a.get("world_pose").truth()))||(std::string(k)=="player"&&(!a.get("participating").truth(true)||!a.get("connected").truth(true))))continue;vehicles.push_back({{k,row.first},static_cast<int>(intField(a,"team")),a.get("x").numeric(),a.get("z").numeric()});}}
 Value context=object(),threats=object(),contributors=array();
 for(int team=1;team<=2;++team){const auto&raw=bases.get(std::to_string(team));if(null(raw))continue;std::vector<std::array<double,3>> circles;auto parse=[&](const Value&p){if(isObject(p)){if(has(p,"x")&&has(p,"z"))circles.push_back({p.get("x").numeric(),p.get("z").numeric(),p.get("radius").numeric(50.)});}else if(isArray(p)&&rows(p).size()>=2)circles.push_back({rows(p)[0].numeric(),rows(p)[1].numeric(),50.});};
 if(isObject(raw)||(isArray(raw)&&rows(raw).size()>=2&&!isObject(rows(raw)[0])&&!isArray(rows(raw)[0])))parse(raw);else for(const auto&p:rows(raw))parse(p);if(circles.empty())continue;
 std::set<std::string> invaders;Value threatened=array();for(std::size_t n=0;n<circles.size();++n){const auto&c=circles[n];bool present=false;for(const auto&v:vehicles)if(v.team==3-team&&(v.x-c[0])*(v.x-c[0])+(v.z-c[1])*(v.z-c[1])<=c[2]*c[2]){invaders.insert(actorString(v.key));present=true;}if(present){Value circle=object();circle.object["id"]=text(std::to_string(team)+":"+std::to_string(n));circle.object["x"]=number(rounded(c[0],3));circle.object["y"]=number(0.);circle.object["z"]=number(rounded(c[1],3));circle.object["radius"]=number(c[2]);threatened.array.push_back(std::move(circle));}}
 threats.object[std::to_string(team)]=std::move(threatened);auto&cap=capture_[team];for(auto i=cap.contributors.begin();i!=cap.contributors.end();)if(!invaders.count(i->first))i=cap.contributors.erase(i);else ++i;for(const auto&v:invaders)cap.contributors.emplace(v,0);int points=0;for(const auto&v:cap.contributors)points+=std::max(0,v.second);points=std::min(100,points);if(!points)cap.participants.clear();auto&base=state_.rules.object["bases"].object[std::to_string(team)];base.kind=Kind::Object;base.object["stopped"]=boolean(false);
 if(!invaders.empty()&&points<100){std::vector<std::string> active(invaders.begin(),invaders.end());for(const auto&v:active)cap.participants.insert(parseActor(v));const auto start=cap.cursor%active.size(),budget=std::min<std::size_t>({3,active.size(),std::size_t(100-points)});for(std::size_t i=0;i<budget;++i){const auto&key=active[(start+i)%active.size()];++cap.contributors[key];increment(parseActor(key),"capture_points");}cap.cursor=(start+budget)%active.size();}else if(invaders.empty())cap.cursor=0;
 points=0;for(const auto&v:cap.contributors){points+=std::max(0,v.second);auto actor=parseActor(v.first);Value row=object();row.object["kind"]=text(actor.first);row.object["id"]=integer(actor.second);row.object["team"]=integer(team);row.object["points"]=integer(v.second);contributors.array.push_back(std::move(row));}points=std::min(100,points);base.object["points"]=integer(points);base.object["invaders"]=integer(static_cast<std::int64_t>(invaders.size()));const auto rate=std::min<std::size_t>(invaders.size(),3);base.object["time_left"]=number(rate?double(std::max(0,100-points))/double(rate):0.);if(points>=100){state_.rules.object["base_captured_team"]=integer(3-team);finish(3-team,"base captured",team);break;}}
 context.object["bases"]=std::move(threats);context.object["states"]=state_.rules.get("bases");context.object["contributors"]=std::move(contributors);context.object["capture_bases"]=bases;context.object["arena_bounds"]=state_.resources.get("arena_bounds");state_.rules.object["capture_context"]=std::move(context);
}
void Rules::maybeFinish(){using namespace rule;if(!accepting()||!null(state_.battle_result))return;const auto&roster=state_.config.get("bot_roster");if(!rows(roster).empty()){std::set<std::int64_t> ids;for(const auto&m:rows(state_.bot_manifest))ids.insert(intField(m,"id"));for(const auto&r:rows(roster))if(!ids.count(intField(r,"id")))return;}if(!state_.config.get("roster_finalized").truth()&&rows(state_.bot_manifest).empty())return;std::set<std::int64_t> participants,living;for(const auto&actors:{&state_.players,&state_.bots})for(const auto&v:*actors){const auto team=intField(v.second,"team");if(team!=1&&team!=2)continue;if(!v.second.get("connected").truth(true))continue;participants.insert(team);if(alive(v.second))living.insert(team);}std::map<int,std::vector<ActorKey>> survivors;std::map<int,int>roster_counts;for(auto*actors:{&state_.players,&state_.bots})for(const auto&row:*actors){const int team=static_cast<int>(intField(row.second,"team"));if((team!=1&&team!=2)||!row.second.get("connected").truth(true))continue;++roster_counts[team];if(alive(row.second)&&row.second.get("participating").truth(true))survivors[team].push_back({actors==&state_.bots?"bot":"player",row.first});}for(int team=1;team<=2;++team)if(survivors[team].size()==1&&roster_counts[team]>=2){auto&row=stats(survivors[team][0]);row.object["lone_stand_enemies"]=integer(std::max<std::int64_t>(intField(row,"lone_stand_enemies"),static_cast<std::int64_t>(survivors[3-team].size())));}if(participants!=std::set<std::int64_t>{1,2}||living.size()==2)return;finish(living.size()==1?static_cast<int>(*living.begin()):0,"team_eliminated");}
}
